import java.io.*;
import java.util.*;

public class A {
    private static List<Long> allNumbers, allSums;

    private static void findAllSubsets(int index, long sumSoFar) {
        if (index == allNumbers.size()) {
            allSums.add(sumSoFar);
            return;
        }
        findAllSubsets(index + 1, sumSoFar + allNumbers.get(index));
        findAllSubsets(index + 1, sumSoFar);
    }

    private static boolean validate(long M, long W, long x) {
        if (x == M) return true;

        long total = x + M;
        while (total > 0) {
            if (total % W > 1) return false;
            total /= W;
        }
        return true;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().split(" ");
        long baseW = Long.parseLong(parts[0]);
        long targetM = Long.parseLong(parts[1]);

        if (baseW == 2) {
            System.out.println("YES");
            return;
        }

        allNumbers = new ArrayList<>();
        allNumbers.add(1L);
        allNumbers.add(baseW);

        long val = baseW;
        final long limit = (long) 1e10;

        while (true) {
            val *= baseW;
            if (val < 0 || val > limit) break;
            allNumbers.add(val);
        }

        allSums = new ArrayList<>();
        findAllSubsets(0, 0);

        boolean answer = false;
        for (long candidate : allSums) {
            answer |= validate(targetM, baseW, candidate);
            if (answer) break;
        }

        System.out.println(answer ? "YES" : "NO");
    }
}
